//! 🧪️ Original typed bytes match independent Serde and physically close every cancellation prefix.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn fund(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn law()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
fn account(p:RetainedCloneProgress,h:semio_framework_trace::HeapAllocationObservation,born:&mut usize,released:&mut usize){assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));*born+=h.requested_bytes;*released+=h.released_bytes;}
#[test]
fn original_typed_operation_bytes_match_independent_serde_and_return_every_backing(){
    for row in law()["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(law()["cancelAt"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){
        let((text,expected),h)=observe(||{let text=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);let mut expected=b"op".to_vec();expected.extend(serde_json::to_vec(&text).unwrap());(text,expected)});let expected_capacity=expected.capacity();let mut born=h.requested_bytes-expected_capacity;let mut released=h.released_bytes;
        let d=RetainedCloneSource::<String>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<String>::constructor_copy_bytes(),..fund(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})};let((mut source,p),h)=observe(||RetainedCloneSource::admit_owned(text,(),g).map_err(|(error,..)|error).unwrap());account(p,h,&mut born,&mut released);
        let((original,p),h)=observe(||source.retain_original(fund(RetainedOwnedProjection::<String>::constructor_demand())).unwrap());account(p,h,&mut born,&mut released);let pointer=original.borrow().unwrap().get().as_ptr();let mut original=Some(original);let d=ArtifactOriginalOperationBytes::<String>::birth_demands();assert!(d.copy_bytes<=4096,"original encoder birth{} exceeds copy quantum; cursor{} output{}",d.copy_bytes,size_of::<ArtifactPreparedOperationCursor>(),size_of::<ArtifactPreparedOperationOutput>());let((mut owner,p),h)=observe(||ArtifactOriginalOperationBytes::admit(&mut original,ArtifactOperationWire::canonical(),1<<20,4<<20,fund(d)).unwrap().unwrap());account(p,h,&mut born,&mut released);assert!(original.is_none());assert_eq!(owner.original.as_ref().unwrap().borrow().unwrap().get().as_ptr(),pointer);
        for turn in 0..100000{if cut.is_some_and(|cut|turn>=cut)||owner.bytes().is_some(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096);for axis in law()["deniedAxes"].as_array().unwrap(){let mut g=fund(d);let limit=match axis.as_str().unwrap(){"items"=>&mut g.maximum_items,"copy"=>&mut g.maximum_copy_bytes,"capacity"=>&mut g.maximum_capacity_bytes,"release"=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let before=(owner.phase,owner.length,owner.offset,owner.output.len(),owner.output.allocated_bytes(),owner.cursor.complete,owner.cursor.closed);let(step,h)=observe(||owner.advance(g).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!((owner.phase,owner.length,owner.offset,owner.output.len(),owner.output.allocated_bytes(),owner.cursor.complete,owner.cursor.closed),before);}
        let(step,h)=observe(||owner.advance(fund(d)).unwrap());account(step.progress(),h,&mut born,&mut released);assert!(turn<99999,"original encoding stalled phase{}",owner.phase);}
        if cut.is_none(){assert_eq!(owner.bytes().unwrap(),expected.as_slice());let pointer=owner.bytes().unwrap().as_ptr();let((bytes,p),h)=observe(||owner.take(fund(owner.demands(4096).unwrap())).unwrap().unwrap());account(p,h,&mut born,&mut released);assert_eq!(bytes.as_ptr(),pointer);let mut close=semio_framework_value::retirement::controlled::ControlledRetirement::new(bytes).unwrap_or_else(|_|panic!("native byte retirement"));while !close.terminal_is_empty(){let d=close.next_demand(4096).unwrap();let(step,h)=observe(||close.step(fund(d)).unwrap());account(step.progress(),h,&mut born,&mut released);}}
        owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();let(step,h)=observe(||owner.close_step(fund(d)).unwrap());account(step.progress(),h,&mut born,&mut released);}let(_,h)=observe(||drop(owner));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();let(step,h)=observe(||source.close_step(fund(d)).unwrap());account(step.progress(),h,&mut born,&mut released);}assert_eq!(born,released);
    }}
}

fn now()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096}}
#[test]
fn original_caller_decoder_receives_outgoing_bytes_and_closes_after_real_token_cancellation(){
    use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
    for cut in std::iter::once(None).chain(law()["cancelAt"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){
        let mut caller=OriginalJobFixtureCaller::admit(OperationId(813),Generation(7),stock(),now,1000,1<<26);let mut decoder=OriginalJobDecodeOwner::empty();
        let text="λ🌿\n".repeat(1300);let expected=[b"op".as_slice(),serde_json::to_vec(&text).unwrap().as_slice()].concat();let d=RetainedCloneSource::<String>::owned_constructor_demand::<()>();let(mut source,_)=RetainedCloneSource::admit_owned(text,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<String>::constructor_copy_bytes(),..fund(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).map_err(|(error,..)|error).unwrap();let mut original=Some(source.retain_original(fund(RetainedOwnedProjection::<String>::constructor_demand())).unwrap().0);let mut owner=None;
        let d=ArtifactOriginalOperationBytes::<String>::birth_demands();let(result,h)=observe(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|admit_original_construction(cx,&mut owner,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let(owner,p)=ArtifactOriginalOperationBytes::admit(&mut original,ArtifactOperationWire::canonical(),1<<20,4<<20,fund(d))?.unwrap();Ok((owner,p))})));assert!(result.unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));let owner=owner.as_mut().unwrap();
        for turn in 0..100000{if cut.is_some_and(|cut|turn>=cut)||owner.bytes().is_some(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096);let(result,h)=observe(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|{let mut posted=None;admit_original_construction(cx,&mut posted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let step=owner.advance(fund(d))?;Ok(((),step.progress()))})}));assert!(result.unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));assert!(turn<99999);}
        if cut.is_none(){assert_eq!(owner.bytes().unwrap(),expected)}else{caller.cancel().cancel_now();let d=owner.demands(4096).unwrap();let phase=owner.phase;assert!(!caller.turn_with_decoder(fund(d),&mut decoder,|cx|{let mut posted=None;admit_original_construction(cx,&mut posted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=owner.advance(fund(d))?.progress();Ok(((),p))})}).unwrap());assert_eq!(owner.phase,phase);assert_eq!(caller.receipt(),Default::default());}
        owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();let(result,h)=observe(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|owner.close_step(g)))));result.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));}
        while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();let(result,h)=observe(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|source.close_step(g)))));result.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));}
        while !decoder.terminal_is_empty(){let d=decoder.retirement_demands(4096).unwrap();let(result,h)=observe(||caller.turn(fund(d),|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|decoder.close_step(g)))));result.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));}caller.retire(stock());
    }
}

#[test]
fn paged_original_payload_matches_independent_serde_without_contiguous_copy(){
    for row in law()["cases"].as_array().unwrap(){
        let text=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);
        let expected=[b"op".as_slice(),serde_json::to_vec(&text).unwrap().as_slice()].concat();
        let d=RetainedCloneSource::<String>::owned_constructor_demand::<()>();
        let(mut source,_)=RetainedCloneSource::admit_owned(text,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<String>::constructor_copy_bytes(),..fund(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).map_err(|(error,..)|error).unwrap();
        let mut original=Some(source.retain_original(fund(RetainedOwnedProjection::<String>::constructor_demand())).unwrap().0);
        let(mut owner,_)=ArtifactOriginalOperationBytes::admit_paged(&mut original,ArtifactOperationWire::canonical(),1<<20,4<<20,fund(ArtifactOriginalOperationBytes::<String>::birth_demands())).unwrap().unwrap();
        for turn in 0..100000{if owner.payload_ready(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096);owner.advance(fund(d)).unwrap();assert!(turn<99999);}
        assert_eq!(owner.payload_len().unwrap(),expected.len());assert!(owner.bytes().is_none());
        let mut output=[0u8;7];let mut offset=0;while offset<expected.len(){let n=owner.read_payload(offset,&mut output).unwrap();assert!(n>0);assert_eq!(&output[..n],&expected[offset..offset+n]);offset+=n;}
        assert_eq!(owner.read_payload(offset,&mut output).unwrap(),0);assert!(owner.read_payload(offset+1,&mut output).is_err());assert!(owner.take(stock()).is_err());
        owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();owner.close_step(fund(d)).unwrap();}
        while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();source.close_step(fund(d)).unwrap();}
    }
}
